import{_ as e,o as t,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-07-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-07-08","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-07-08.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-07-08.md","lastUpdated":null}'),n={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-07-08.md"};function i(s,o,l,d,g,c){return t(),a("div",null,[...o[0]||(o[0]=[r('<p>Now I&#39;ll put together the meeting summary in Chinese.--- title: Ceph RGW Refactoring Meeting 2026-07-08 date: 2026-07-10 updated: 2026-07-11 tags:</p><ul><li>RGW</li><li>会议纪要</li><li>元数据</li><li>社区动态 categories:</li><li>视频总结 subtitle: Ceph_RGW_Refactoring_Meeting_2026-07-08</li></ul><hr><h1 id="ceph-rgw-refactoring-会议纪要-2026-07-08" tabindex="-1">Ceph RGW Refactoring 会议纪要（2026-07-08） <a class="header-anchor" href="#ceph-rgw-refactoring-会议纪要-2026-07-08" aria-label="Permalink to &quot;Ceph RGW Refactoring 会议纪要（2026-07-08）&quot;">​</a></h1><p>本次会议围绕 RGW（radosgw）方向的三个主要议题展开：radosgw-admin CLI 重构（GSoC 项目）、RGW 元数据外置到外部键值存储、以及若干安全与限流相关的 PR 讨论。以下是各议题的详细纪要。</p><h2 id="议题一-radosgw-admin-与-cli11-重构-google-summer-of-code-项目" tabindex="-1">议题一：radosgw-admin 与 CLI11 重构（Google Summer of Code 项目） <a class="header-anchor" href="#议题一-radosgw-admin-与-cli11-重构-google-summer-of-code-项目" aria-label="Permalink to &quot;议题一：radosgw-admin 与 CLI11 重构（Google Summer of Code 项目）&quot;">​</a></h2><p>一位 Google Summer of Code（GSoC）暑期项目的学生介绍了他在导师指导下进行的 radosgw-admin 命令行工具重构工作，目标是让这套 CLI 对用户和开发者都更加友好。</p><h3 id="当前痛点" tabindex="-1">当前痛点 <a class="header-anchor" href="#当前痛点" aria-label="Permalink to &quot;当前痛点&quot;">​</a></h3><p>演讲者首先梳理了 radosgw-admin 现状中的几个核心问题：</p><ul><li><strong>三处信息来源不一致</strong>：命令与选项分散在代码本身、<code>--help</code> 输出和 man page 三个地方，彼此并不对齐。目前有 <strong>68 个命令</strong>和 <strong>46 个 flag</strong> 根本没有出现在 man page 中。</li><li><strong>代码分散</strong>：整套逻辑散落在约 <strong>14000 行代码</strong>里，命令的定义、命令解析、flag 解析、以及具体实现各自分布在不同位置。开发者若想修改或新增一个命令，需要在多个地方同步维护。</li><li><strong>help 输出过长</strong>：<code>--help</code> 一次性输出约 <strong>400 行</strong>，用户在真正需要帮助时反而无法有效使用。</li></ul><h3 id="重构目标与思路" tabindex="-1">重构目标与思路 <a class="header-anchor" href="#重构目标与思路" aria-label="Permalink to &quot;重构目标与思路&quot;">​</a></h3><p>核心思路是建立<strong>单一可信来源（single source of truth）</strong>：以代码为准，自动生成 <code>--help</code> 输出和 man page。具体目标包括：</p><ul><li>将某条命令的名称、描述、选项、行为集中定义在同一处。</li><li>help 输出具备<strong>分层结构</strong>，例如只查看 <code>bucket</code> 的帮助，或只查看 <code>bucket logging flush</code> 的帮助。</li><li>在整个过程中，<strong>保持向后兼容性（backward compatibility）</strong>，这是最重要也是最困难的部分。</li></ul><p>实现方式采取渐进式迁移，按命令族（family）逐个推进，目前 script 族和 bucket 族已接近完成，这样也便于代码 review。迁移过程中所有命令的<strong>实现、描述等数据保持不变</strong>，只改变命令的解析方式；已迁移命令由新的 CLI11 代码处理，未迁移命令仍由原有代码处理，两套代码并存。</p><h3 id="迁移后命令的结构" tabindex="-1">迁移后命令的结构 <a class="header-anchor" href="#迁移后命令的结构" aria-label="Permalink to &quot;迁移后命令的结构&quot;">​</a></h3><p>以三级命令 <code>bucket logging flush</code> 为例：<code>bucket</code> 注册在 root（app）上，<code>logging</code> 作为 <code>bucket</code> 的子命令注册，<code>flush</code> 再作为 <code>bucket logging</code> 的子命令注册；随后为其添加选项，如 <code>--bucket</code> / <code>-b</code>（互为别名，注册为同一含义）以及 <code>--bucket-id</code>。注册之后是实现回调，实际代码在所有命令注册、初始化和 driver 初始化完成后，通过 CLI action 调用执行。</p><p>选项分为两部分：命令自身的选项，以及全局选项（如 <code>tenant</code> 和 <code>uid</code>）。由于这些全局选项在代码中共享初始化逻辑，目前将其作为全局选项，会出现在每个命令中。当前使用临时 flag <code>--111-help</code>，未来会替换为标准的 <code>--help</code>。</p><h3 id="向后兼容的难点与处理" tabindex="-1">向后兼容的难点与处理 <a class="header-anchor" href="#向后兼容的难点与处理" aria-label="Permalink to &quot;向后兼容的难点与处理&quot;">​</a></h3><p>演讲者列举了几类实际遇到并已解决的兼容性场景：</p><ul><li><strong>flag 位置</strong>：原代码中 flag 可以出现在命令前后任意位置；CLI11 要求 flag 注册到特定命令上。当前做法是接受这种用法但给出<strong>警告</strong>，提示 flag 应出现在子命令之后（<code>uid</code> 作为全局 flag 仍可任意位置出现）。</li><li><strong>重复 flag</strong>：例如 <code>uid</code> 或 <code>bucket</code> 出现两次，原代码静默接受，现在保留接受行为但<strong>增加警告</strong>。</li><li><strong>二元（binary）flag</strong>：如 <code>--fixed</code>，原代码将其注册为整数并接受多种写法，比如其后跟 <code>false</code> 会关闭该 flag，而 CLI11 只支持等号形式。已调整为兼容原行为；另如 <code>--fix=banana</code> 在原代码中也会被接受并打开 flag，现同样接受但给出警告。</li><li><strong>未识别输入</strong>：对与命令无关的 flag（如 <code>bucket stats</code> 后跟无关的 <code>--fix</code>），原代码静默忽略，现在改为警告；对完全未识别的 flag 或多余单词，则与原代码一致直接报错。</li><li><strong>别名支持</strong>：如 <code>bucket rad list</code> 与 <code>bucket rados list</code>、<code>rm</code> 与 <code>remove</code>、<code>shared object</code> 与 <code>shared objects</code>，以及选项 <code>-b</code> / <code>--bucket</code> 等，均保持等价支持。</li></ul><h3 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h3><p>剩余工作是迁移其余全部命令，由于大部分兼容性问题已在前期解决，预计推进会比之前快。后续还需精炼内部结构以提升可读性和可维护性；迁移完成后可评估是否移除部分兼容处理逻辑或直接调整代码（届时不再有 legacy 代码）。关于是否把那 10 个全局选项也交给 CLI11 解析仍未决定，目前仍按原代码方式在 CLI11 之前解析。</p><h3 id="讨论与决定事项" tabindex="-1">讨论与决定事项 <a class="header-anchor" href="#讨论与决定事项" aria-label="Permalink to &quot;讨论与决定事项&quot;">​</a></h3><ul><li><strong>是否需要对&quot;错误用例&quot;保持向后兼容</strong>（重复 flag、未知 flag 等）：与会者倾向于，如果这些情况本身就是命令的错误，直接失败并给出清晰错误信息是合理的；同时不希望不必要地破坏用户已有的自动化脚本。共识是采用<strong>两阶段策略</strong>——先警告，未来版本再真正报错。对自动化脚本因版本升级而突然失败要格外谨慎。</li><li><strong>测试验证</strong>：Casey 建议将已编写的 shell 测试脚本（如 <code>test-cli11-bucket.sh</code> 等）在<strong>未修改的 radosgw-admin</strong> 上先跑一遍，验证迁移前后相同命令、参数和错误行为一致。进一步建议将这些测试<strong>拆分为独立 PR</strong>，作为新的 RGW 测试子套件（subsuite），可在 Teuthology 中运行，并作为主体重构 PR 合并的门禁（gate）。演讲者接受这一建议。大家一致认为 radosgw-admin 命令面（surface area）极大而测试覆盖不足，存在破坏后不易察觉的风险。</li><li><strong>错误信息与退出码</strong>：一致认为<strong>错误信息文本不应保持兼容</strong>——任何依赖具体错误文本的测试或脚本本身就是脆弱且错误的。测试应放宽对错误/警告文本的匹配，改为依赖<strong>返回码</strong>。但需要注意退出码：原代码在某些情况返回 22（EINVAL）、20 等，而 CLI11 出现了 104 之类的值，这被认为不合理。决定事项是<strong>尽量沿用与之前一致的退出码</strong>（如查询不存在实体返回 ENOENT、参数错误返回 EINVAL），演讲者将进一步排查 104 的问题。</li></ul><h2 id="议题二-在-rgw-中外置元数据-externalizing-metadata-akamai-提出" tabindex="-1">议题二：在 RGW 中外置元数据（Externalizing metadata，Akamai 提出） <a class="header-anchor" href="#议题二-在-rgw-中外置元数据-externalizing-metadata-akamai-提出" aria-label="Permalink to &quot;议题二：在 RGW 中外置元数据（Externalizing metadata，Akamai 提出）&quot;">​</a></h2><p>来自 Akamai 的 Leslie 介绍，他们此前与 Kyle Bader 进行过高层交流，探索将元数据外置的方向，并了解到已有一个将 <strong>bucket index</strong> 外置到 <strong>FoundationDB</strong> 的项目在进行中。Akamai 希望参与其中：FoundationDB 可以作为&quot;黄金路径（golden path）&quot;，但他们更希望首先加入对 <strong>TiKV</strong> 的支持，并推动改造使得外部存储能够更<strong>通用地可插拔（pluggable）</strong>。他们注意到近期用于 FoundationDB 的实验性库已合入，可以据此为 TiKV 做类似工作，并希望与相关团队协作。</p><p>Gabby 表示自己正在做一个类似的设计，研究用 FoundationDB 和 TiKV 将 <strong>S3 对象身份（identity）与 RADOS 对象解耦</strong>。当前 S3 对象身份与 RADOS 对象几乎是一对一绑定，导致改名需要拷贝整个对象数据，也难以将多个小对象打包（packing）进一个大实体。这属于更大规模 schema 变更的一部分。</p><h3 id="为何关注-tikv-与-foundationdb" tabindex="-1">为何关注 TiKV 与 FoundationDB <a class="header-anchor" href="#为何关注-tikv-与-foundationdb" aria-label="Permalink to &quot;为何关注 TiKV 与 FoundationDB&quot;">​</a></h3><ul><li>Gabby 最初的设计是**数据库无关（database agnostic）**的，只假设一个键值系统，理论上可替换后端。</li><li><strong>FoundationDB 的扩展上限</strong>：Apple 在设计上硬性限制了扩展能力，单集群约可扩展到 <strong>640 亿（64 billion）</strong> 键值/对象，努力时或许可翻倍；超过该规模需要管理一整个 FoundationDB 集群队列（fleet）。</li><li><strong>TiKV 的扩展能力</strong>：单集群按设计可扩展到约<strong>一万亿（1 trillion）</strong> KV，比 FoundationDB 大至少一个数量级；推很狠时约可达 8000 亿到 1 万亿，但会付出性能代价。</li><li>Akamai 选择 TiKV 的理由还包括他们已在生产中大规模运行 TiDB/TiKV，拥有丰富的运维知识；同时 TiKV 的扩展特性与性能特性与 FoundationDB 不同。</li><li>FoundationDB 的吸引力在于<strong>更可预测的性能</strong>，以及插入与删除之间更接近对称的行为（perfect symmetry），这一点在 <strong>LSM tree</strong> 系统上并不成立。大家明确表示不希望重蹈 <strong>RocksDB</strong> 性能特性的覆辙——这也是希望把这类元数据移出 RADOS 的部分原因。Gabby 的 sharding 与 schema 归一化（normalization）方式对某些事务性操作会有影响，正对 FoundationDB 的一些假设形成挑战。</li></ul><h3 id="是否同时支持两种数据库" tabindex="-1">是否同时支持两种数据库 <a class="header-anchor" href="#是否同时支持两种数据库" aria-label="Permalink to &quot;是否同时支持两种数据库&quot;">​</a></h3><p>会上出现了同时支持两种数据库的设想：例如 <strong>archive zone</strong>（写一次、从不删除）非常适合 LSM tree，因为吸收写入很快且不必处理 tombstone；而对于持续变化的<strong>生产 zone</strong>，则更适合 FoundationDB 的 redwood tree，以避免因 tombstone 而卡住。因此理论上可以同时支持两种系统，让客户为不同 zone 分配不同数据库。当扩展规模在数百亿对象量级时，FoundationDB 与 TiKV 可用相同设计；一旦要扩展到万亿级对象，则因 FoundationDB 的限制需要不同的 scheme。</p><h3 id="范围界定" tabindex="-1">范围界定 <a class="header-anchor" href="#范围界定" aria-label="Permalink to &quot;范围界定&quot;">​</a></h3><p>关于工作范围，与会者明确讨论了这不仅是加速和扩展 <strong>bucket index</strong>，还包括：将部分（并非全部）对象元数据（object metadata）移入该层；实现名称与位置（location）之间的交互，以支持对象打包（packing）和前缀重命名（prefix rename）等用例。共识是元数据的核心仍是 <strong>bucket index 和对象属性（object attributes）</strong>，会紧贴这一核心，而非把用户数据库等其它随机数据库都纳入。Gabby 的设计文档同时覆盖了更多场景，这些场景也在视野之内。</p><h3 id="决定事项与后续行动" tabindex="-1">决定事项与后续行动 <a class="header-anchor" href="#决定事项与后续行动" aria-label="Permalink to &quot;决定事项与后续行动&quot;">​</a></h3><ul><li>一个早期目标是<strong>在 RGW 之外构建原型</strong>，对其施加负载以评估扩展特性；Casey 建议在同一代码库中同时支持两种数据库，从而摸清所需的抽象层。整体保持<strong>审慎但持续推进</strong>的节奏，早期设计尽量保持 <strong>schema 无关</strong>。</li><li>决定采取<strong>渐进式协作</strong>，各方在不过早锁定方案的前提下迭代前进。将在<strong>上游 RGW develop Slack 频道</strong>继续讨论，并可能另开一个专门 forum 同步（Gabby 在以色列，与英国时区相近，便于协调）。</li><li>Gabby 的设计文档目前较长（每篇约 16 页且属 NDA 范畴），他将整理出精简版（TL;DR，约 5-6 页）便于他人阅读，先通过 Google Doc 协作，并从 Slack 频道链接。<strong>一致同意</strong>：待设计与架构文档成熟后，应作为设计文档 PR 提交进代码库，因为这属于系统的核心设计，需要被妥善保存。Gabby 欢迎任何对 RGW 熟悉的人参与 review 和反馈。</li></ul><h2 id="议题三-aes-256-gcm-可配置-chunk-size" tabindex="-1">议题三：AES-256-GCM 可配置 chunk size <a class="header-anchor" href="#议题三-aes-256-gcm-可配置-chunk-size" aria-label="Permalink to &quot;议题三：AES-256-GCM 可配置 chunk size&quot;">​</a></h2><p>一位提交者介绍了一个后续 PR：为新的 <strong>AES-256-GCM</strong> 实现添加可配置的 chunk size。这是基于与 IBM 侧安全团队交流后的跟进工作。默认仍保持 <strong>4K</strong>，但允许运维者可选切换到 <strong>64K</strong>。提交者曾考虑根据对象大小自动配置 chunk size，但尚未着手，且对如何正确测试与排障存在顾虑，因此暂以当前形式提交 PR。</p><h2 id="议题四-社区提交的分布式限流-distributed-rate-limiting-pr" tabindex="-1">议题四：社区提交的分布式限流（distributed rate limiting）PR <a class="header-anchor" href="#议题四-社区提交的分布式限流-distributed-rate-limiting-pr" aria-label="Permalink to &quot;议题四：社区提交的分布式限流（distributed rate limiting）PR&quot;">​</a></h2><p>Casey 提出一个社区用户提交的、较有争议的 PR，希望引起大家关注。该 PR 实现分布式限流：RADOS 后端为此新增一个 cls，所有限流检查以写请求形式发送到 OSD，由 OSD 判定请求是否被限流。Casey 已在 PR 中留下对其设计与扩展性的疑虑。</p><p>讨论要点与倾向：</p><ul><li>与会者认为该功能有价值，但对<strong>性能</strong>普遍存疑。多数大规模使用 radosgw 的用户已在前端自建 proxy 来处理限流。若能集成进 RADOS 固然好，但前提是必须具备扩展能力。</li><li>核心异议在于：<strong>限流本质是短暂性（ephemeral）信息，不应存储在 RADOS 中</strong>。有观点认为更合理的是由 carrier 层或自有 tier 来处理。结论倾向是：<strong>不反对</strong>有人做这件事、也不反对提供一种派发到 RADOS 的方式，但<strong>不希望将其作为唯一实现而产生依赖</strong>，需要保留抽象。</li><li>存在真实用户需求——几年前就有过在多个 RGW 之间做分布式限流的尝试，NFS Ganesha 也有类似机制（在 RGW 之间传递 quota）。</li><li>Casey 的建议是：使用 RADOS 的 <strong>watch/notify</strong> 在各网关之间共享内存中的计数器（counters）表示，接受一个略微不一致的全局视图，而不要求完全一致。这与 NFS Ganesha 的做法本质相同——后者按固定间隔发送增量（delta）变化，只需一个通信基底（communication substrate），watch/notify 即可胜任。</li></ul><h2 id="会议收尾" tabindex="-1">会议收尾 <a class="header-anchor" href="#会议收尾" aria-label="Permalink to &quot;会议收尾&quot;">​</a></h2><p>会议达到一小时时限后结束。主持人提醒：次日有 RGW office hours，下周还有一次会议，希望继续讨论的成员可在这些场合继续交流。</p>',43)])])}const p=e(n,[["render",i]]);export{u as __pageData,p as default};
